    try:
        content = "NovaMind continues to scale seamlessly on Tier 1 infrastructure with sub-185ms P95 latency and zero downtime across our growing user base."
        res_post = nm.marketing.post_social_media(content=content)
        print("Social Media Post:", res_post)
    except Exception as e:
        print("Social Media Post failed:", e)

if __name__ == "__main__":
    run_week8()

